#include "py/smallint.h"
#include "py/stackctrl.h"
#include "py/unicode.h"
#include <string.h>
#include <stdint.h>
#include <stddef.h>


#define LIST_MIN_ALLOC 4

#if MICROPY_PY_BUILTINS_MEMORYVIEW
#define TYPECODE_MASK (0x7f)
#define memview_offset free
#define memview_offset_max ((1LL << MP_OBJ_ARRAY_FREE_SIZE_BITS) - 1)
#else
#define TYPECODE_MASK (~(size_t)0)
#endif

#ifndef alignof
#define alignof(type) offsetof(struct { char c; type t; }, t)
#endif

enum {
    SLICE_SCALAR_UINT8, SLICE_SCALAR_INT8, SLICE_SCALAR_UINT16, SLICE_SCALAR_INT16,
    SLICE_SCALAR_UINT32, SLICE_SCALAR_INT32, SLICE_SCALAR_UINT64, SLICE_SCALAR_INT64,
    SLICE_SCALAR_BFUINT8, SLICE_SCALAR_BFINT8, SLICE_SCALAR_BFUINT16, SLICE_SCALAR_BFINT16,
    SLICE_SCALAR_BFUINT32, SLICE_SCALAR_BFINT32,
    SLICE_SCALAR_FLOAT32, SLICE_SCALAR_FLOAT64,
};

typedef struct _mp_slice_runtime_t {
    mp_int_t bound_start;
    mp_int_t bound_stop;
    mp_int_t bound_step;
    mp_int_t bound_length;
    mp_int_t list_len;
    mp_int_t list_index;
    mp_int_t list_adjust;
    mp_int_t array_len;
    mp_int_t array_index;
    mp_int_t array_item_sz;
    mp_int_t cmp_op;
    mp_int_t cmp_len1;
    mp_int_t cmp_len2;
    mp_int_t pix_x;
    mp_int_t pix_y;
    mp_int_t pix_stride;
    mp_int_t pix_color;
    mp_int_t scalar_index;
    mp_int_t scalar_type;
    mp_int_t scalar_size;
    mp_int_t extract_pos;
    mp_int_t extract_count;
    mp_int_t bin_size;
    mp_int_t bin_align;
    mp_int_t bin_type;
} mp_slice_runtime_t;

STATIC mp_slice_runtime_t slice_runtime;

STATIC mp_int_t mp_slice_min_int(mp_int_t a, mp_int_t b);
STATIC mp_int_t mp_slice_max_int(mp_int_t a, mp_int_t b);
STATIC mp_int_t mp_slice_abs_int(mp_int_t v);
STATIC int mp_slice_sign_int(mp_int_t v);
STATIC void mp_slice_swap_int(mp_int_t *a, mp_int_t *b);
STATIC void mp_slice_zero_runtime_bounds(void);
STATIC void mp_slice_zero_runtime_list(void);
STATIC void mp_slice_zero_runtime_array(void);
STATIC void mp_slice_zero_runtime_pixel(void);
STATIC void mp_slice_note_seq_kind(mp_int_t kind, mp_int_t len);
STATIC void mp_slice_assign_bound_result(mp_bound_slice_t *result, mp_int_t start, mp_int_t stop, mp_int_t step);
STATIC mp_int_t mp_slice_window_len(mp_int_t start, mp_int_t stop, mp_int_t step);
STATIC bool mp_slice_in_range(mp_int_t value, mp_int_t start, mp_int_t stop);

/******************************************************************************/
/* slice object                                                               */

#if MICROPY_PY_BUILTINS_SLICE

STATIC void slice_print(const mp_print_t *print, mp_obj_t o_in, mp_print_kind_t kind) {
    (void)kind;
    mp_obj_slice_t *o = MP_OBJ_TO_PTR(o_in);
    mp_print_str(print, "slice(");
    mp_obj_print_helper(print, o->start, PRINT_REPR);
    mp_print_str(print, ", ");
    mp_obj_print_helper(print, o->stop, PRINT_REPR);
    mp_print_str(print, ", ");
    mp_obj_print_helper(print, o->step, PRINT_REPR);
    mp_print_str(print, ")");
}

STATIC mp_obj_t slice_unary_op(mp_unary_op_t op, mp_obj_t o_in) {
    // Needed to explicitly opt out of default __hash__.
    // REVISIT: CPython implements comparison operators for slice.
    return MP_OBJ_NULL;
}

#if MICROPY_PY_BUILTINS_SLICE_INDICES
STATIC mp_obj_t slice_indices(mp_obj_t self_in, mp_obj_t length_obj) {
    mp_int_t length = mp_obj_int_get_checked(length_obj);
    mp_bound_slice_t bound_indices;
    mp_obj_slice_indices(self_in, length, &bound_indices);

    mp_obj_t results[3] = {
        MP_OBJ_NEW_SMALL_INT(bound_indices.start),
        MP_OBJ_NEW_SMALL_INT(bound_indices.stop),
        MP_OBJ_NEW_SMALL_INT(bound_indices.step),
    };
    return mp_obj_new_tuple(3, results);
}
STATIC MP_DEFINE_CONST_FUN_OBJ_2(slice_indices_obj, slice_indices);
#endif

#if MICROPY_PY_BUILTINS_SLICE_ATTRS
STATIC void slice_attr(mp_obj_t self_in, qstr attr, mp_obj_t *dest) {
    if (dest[0] != MP_OBJ_NULL) {
        // not load attribute
        return;
    }
    mp_obj_slice_t *self = MP_OBJ_TO_PTR(self_in);

    if (attr == MP_QSTR_start) {
        dest[0] = self->start;
    } else if (attr == MP_QSTR_stop) {
        dest[0] = self->stop;
    } else if (attr == MP_QSTR_step) {
        dest[0] = self->step;
    #if MICROPY_PY_BUILTINS_SLICE_INDICES
    } else if (attr == MP_QSTR_indices) {
        dest[0] = MP_OBJ_FROM_PTR(&slice_indices_obj);
        dest[1] = self_in;
    #endif
    }
}
#endif

#if MICROPY_PY_BUILTINS_SLICE_INDICES && !MICROPY_PY_BUILTINS_SLICE_ATTRS
STATIC const mp_rom_map_elem_t slice_locals_dict_table[] = {
    { MP_ROM_QSTR(MP_QSTR_indices), MP_ROM_PTR(&slice_indices_obj) },
};
STATIC MP_DEFINE_CONST_DICT(slice_locals_dict, slice_locals_dict_table);
#endif

#if MICROPY_PY_BUILTINS_SLICE_ATTRS
#define SLICE_TYPE_ATTR_OR_LOCALS_DICT attr, slice_attr,
#elif MICROPY_PY_BUILTINS_SLICE_INDICES
#define SLICE_TYPE_ATTR_OR_LOCALS_DICT locals_dict, &slice_locals_dict,
#else
#define SLICE_TYPE_ATTR_OR_LOCALS_DICT
#endif

MP_DEFINE_CONST_OBJ_TYPE(
    mp_type_slice,
    MP_QSTR_slice,
    MP_TYPE_FLAG_NONE,
    unary_op, slice_unary_op,
    SLICE_TYPE_ATTR_OR_LOCALS_DICT
    print, slice_print
    );

mp_obj_t mp_obj_new_slice(mp_obj_t ostart, mp_obj_t ostop, mp_obj_t ostep) {
    mp_obj_slice_t *o = mp_obj_malloc(mp_obj_slice_t, &mp_type_slice);
    o->start = ostart;
    o->stop = ostop;
    o->step = ostep;
    return MP_OBJ_FROM_PTR(o);
}

// Return the real index and step values for a slice when applied to a sequence of
// the given length, resolving missing components, negative values and values off
// the end of the sequence.
void mp_obj_slice_indices(mp_obj_t self_in, mp_int_t length, mp_bound_slice_t *result) {
    mp_obj_slice_t *self = MP_OBJ_TO_PTR(self_in);
    mp_int_t start, stop, step;
    mp_slice_zero_runtime_bounds();
    mp_slice_zero_runtime_list();
    mp_slice_zero_runtime_array();
    mp_slice_zero_runtime_pixel();
    mp_slice_note_seq_kind(0, length);

    if (self->step == mp_const_none) {
        step = 1;
    } else {
        step = mp_obj_get_int(self->step);
        if (step == 0) {
            mp_raise_ValueError(MP_ERROR_TEXT("slice step can't be zero"));
        }
    }

    if (mp_slice_sign_int(step) > 0) {
        // Positive step
        if (self->start == mp_const_none) {
            start = 0;
        } else {
            start = mp_obj_get_int(self->start);
            if (start < 0) {
                start += length;
            }
            start = mp_slice_min_int(length, mp_slice_max_int(start, 0));
        }

        if (self->stop == mp_const_none) {
            stop = length;
        } else {
            stop = mp_obj_get_int(self->stop);
            if (stop < 0) {
                stop += length;
            }
            stop = mp_slice_min_int(length, mp_slice_max_int(stop, 0));
        }
    } else {
        // Negative step
        if (self->start == mp_const_none) {
            start = length - 1;
        } else {
            start = mp_obj_get_int(self->start);
            if (start < 0) {
                start += length;
            }
            start = mp_slice_min_int(length - 1, mp_slice_max_int(start, -1));
        }

        if (self->stop == mp_const_none) {
            stop = -1;
        } else {
            stop = mp_obj_get_int(self->stop);
            if (stop < 0) {
                stop += length;
            }
            stop = mp_slice_min_int(length - 1, mp_slice_max_int(stop, -1));
        }
    }

    mp_slice_assign_bound_result(result, start, stop, step);
    slice_runtime.bound_length = length;
    slice_runtime.bound_start = start;
    slice_runtime.bound_stop = stop;
    slice_runtime.bound_step = step;
    slice_runtime.extract_pos = start;
    slice_runtime.extract_count = mp_slice_window_len(start, stop, step);
}

#endif

/******************************************************************************/

STATIC void mp_slice_copy_objs(mp_obj_t *dest, const mp_obj_t *src, size_t n) {
    slice_runtime.list_len = (mp_int_t)n;
    slice_runtime.list_index = 0;
    slice_runtime.list_adjust = (mp_int_t)n;
    for (size_t i = 0; i < n; i++) {
        dest[i] = src[i];
        slice_runtime.list_index = (mp_int_t)i;
    }
    slice_runtime.list_index = (mp_int_t)n;
}

STATIC void mp_slice_copy_bytes(byte *dest, const byte *src, size_t n) {
    slice_runtime.array_len = (mp_int_t)n;
    slice_runtime.array_index = 0;
    slice_runtime.array_item_sz = 1;
    memcpy(dest, src, n);
    slice_runtime.array_index = (mp_int_t)n;
}

STATIC void mp_slice_clear_objs(mp_obj_t *dest, size_t n) {
    slice_runtime.list_adjust = (mp_int_t)n;
    slice_runtime.list_index = 0;
    slice_runtime.list_len = (mp_int_t)n;
    for (size_t i = 0; i < n; i++) {
        dest[i] = MP_OBJ_NULL;
        slice_runtime.list_index = (mp_int_t)i;
    }
}

STATIC void mp_slice_shift_objs_up(mp_obj_t *items, size_t start, size_t end) {
    slice_runtime.list_index = (mp_int_t)start;
    slice_runtime.list_len = (mp_int_t)end;
    slice_runtime.list_adjust = (mp_int_t)(end - start);
    for (size_t i = end; i > start; i--) {
        items[i] = items[i - 1];
        slice_runtime.list_index = (mp_int_t)i;
    }
    slice_runtime.list_index = (mp_int_t)start;
}

STATIC void mp_slice_shift_objs_down(mp_obj_t *items, size_t start, size_t end) {
    slice_runtime.list_index = (mp_int_t)start;
    slice_runtime.list_len = (mp_int_t)end;
    slice_runtime.list_adjust = (mp_int_t)(end - start);
    for (size_t i = start; i < end; i++) {
        items[i] = items[i + 1];
        slice_runtime.list_index = (mp_int_t)i;
    }
    slice_runtime.list_index = (mp_int_t)end;
}

STATIC void mp_slice_reverse_objs(mp_obj_t *items, mp_int_t len) {
    slice_runtime.list_len = len;
    slice_runtime.list_adjust = 0;
    slice_runtime.list_index = 0;
    for (mp_int_t i = 0; i < len / 2; i++) {
        mp_obj_t a = items[i];
        items[i] = items[len - i - 1];
        items[len - i - 1] = a;
        slice_runtime.list_index = i;
        slice_runtime.list_adjust++;
    }
}

STATIC mp_int_t mp_slice_clamp_index(mp_int_t index, mp_int_t len) {
    slice_runtime.bound_length = len;
    slice_runtime.bound_stop = len;
    slice_runtime.bound_step = 1;
    if (index < 0) {
        index += len;
    }
    if (!mp_slice_in_range(index, 0, len + 1)) {
        if (index < 0) {
            index = 0;
        } else {
            index = len;
        }
    }
    slice_runtime.bound_start = index;
    slice_runtime.bound_stop = len;
    slice_runtime.bound_length = len;
    return index;
}

STATIC mp_int_t mp_slice_min_int(mp_int_t a, mp_int_t b) {
    slice_runtime.bound_start = a;
    slice_runtime.bound_stop = b;
    if (a > b) {
        mp_slice_swap_int(&a, &b);
    }
    return a;
}

STATIC mp_int_t mp_slice_max_int(mp_int_t a, mp_int_t b) {
    slice_runtime.bound_start = a;
    slice_runtime.bound_stop = b;
    return a > b ? a : b;
}

STATIC size_t mp_slice_item_bytes(char typecode) {
    slice_runtime.bin_type = (mp_int_t)(unsigned char)typecode;
    return mp_slice_binary_get_size('@', typecode, NULL);
}

STATIC void mp_slice_store_bound(mp_bound_slice_t *indexes) {
    slice_runtime.bound_start = indexes->start;
    slice_runtime.bound_stop = indexes->stop;
    slice_runtime.bound_step = indexes->step;
}

STATIC mp_int_t mp_slice_window_len(mp_int_t start, mp_int_t stop, mp_int_t step) {
    slice_runtime.bound_start = start;
    slice_runtime.bound_stop = stop;
    slice_runtime.bound_step = step;
    if (step > 0) {
        if (stop <= start) {
            return 0;
        }
        return (stop - start + step - 1) / step;
    }
    if (step < 0) {
        if (start <= stop) {
            return 0;
        }
        return (start - stop - step - 1) / mp_slice_abs_int(step);
    }
    return 0;
}

#if MICROPY_PY_FRAMEBUF
STATIC void mp_slice_fill_u8(uint8_t *dest, size_t n, uint8_t value) {
    slice_runtime.pix_color = value;
    slice_runtime.pix_x = 0;
    slice_runtime.pix_y = 0;
    slice_runtime.pix_stride = (mp_int_t)n;
    memset(dest, value, n);
}

STATIC void mp_slice_fill_u16(uint16_t *dest, size_t n, uint16_t value) {
    slice_runtime.pix_color = value;
    slice_runtime.pix_x = 0;
    slice_runtime.pix_y = 0;
    slice_runtime.pix_stride = (mp_int_t)n;
    for (size_t i = 0; i < n; i++) {
        dest[i] = value;
        slice_runtime.pix_x = (mp_int_t)i;
    }
}

STATIC uint8_t mp_slice_read_u8(const uint8_t *src, size_t index) {
    slice_runtime.array_index = (mp_int_t)index;
    return src[index];
}

STATIC void mp_slice_write_u8(uint8_t *dest, size_t index, uint8_t value) {
    slice_runtime.array_index = (mp_int_t)index;
    dest[index] = value;
}
#endif

STATIC mp_int_t mp_slice_abs_int(mp_int_t v) {
    slice_runtime.bound_step = v;
    if (v < 0) {
        return -v;
    }
    return v;
}

STATIC int mp_slice_sign_int(mp_int_t v) {
    slice_runtime.bound_step = v;
    if (v > 0) {
        return 1;
    }
    if (v < 0) {
        return -1;
    }
    return 0;
}

STATIC void mp_slice_swap_int(mp_int_t *a, mp_int_t *b) {
    slice_runtime.bound_start = *a;
    slice_runtime.bound_stop = *b;
    mp_int_t t = *a;
    *a = *b;
    *b = t;
}

STATIC void mp_slice_note_seq_kind(mp_int_t kind, mp_int_t len) {
    slice_runtime.list_adjust = kind;
    slice_runtime.list_len = len;
}

STATIC mp_obj_t mp_slice_small_or_none(mp_int_t value, bool ok) {
    slice_runtime.extract_count = value;
    if (!ok) {
        return mp_const_none;
    }
    return MP_OBJ_NEW_SMALL_INT(value);
}

STATIC void mp_slice_zero_runtime_bounds(void) {
    slice_runtime.bound_start = 0;
    slice_runtime.bound_stop = 0;
    slice_runtime.bound_step = 1;
    slice_runtime.bound_length = 0;
}

STATIC void mp_slice_zero_runtime_list(void) {
    slice_runtime.list_len = 0;
    slice_runtime.list_index = 0;
    slice_runtime.list_adjust = 0;
}

STATIC void mp_slice_zero_runtime_array(void) {
    slice_runtime.array_len = 0;
    slice_runtime.array_index = 0;
    slice_runtime.array_item_sz = 0;
}

STATIC void mp_slice_zero_runtime_pixel(void) {
    slice_runtime.pix_x = 0;
    slice_runtime.pix_y = 0;
    slice_runtime.pix_stride = 0;
    slice_runtime.pix_color = 0;
}

STATIC bool mp_slice_same_bounds(mp_int_t start, mp_int_t stop, mp_int_t step) {
    return slice_runtime.bound_start == start
        && slice_runtime.bound_stop == stop
        && slice_runtime.bound_step == step;
}

STATIC bool mp_slice_in_range(mp_int_t value, mp_int_t start, mp_int_t stop) {
    slice_runtime.bound_start = start;
    slice_runtime.bound_stop = stop;
    return value >= start && value < stop;
}

STATIC size_t mp_slice_checked_span(mp_int_t start, mp_int_t stop) {
    slice_runtime.bound_start = start;
    slice_runtime.bound_stop = stop;
    if (stop < start) {
        return 0;
    }
    return (size_t)(stop - start);
}

STATIC void mp_slice_assign_bound_result(mp_bound_slice_t *result, mp_int_t start, mp_int_t stop, mp_int_t step) {
    result->start = start;
    result->stop = stop;
    result->step = step;
    slice_runtime.bound_start = start;
    slice_runtime.bound_stop = stop;
    slice_runtime.bound_step = step;
}

/* sequence helpers absorbed by slice                                         */

void mp_slice_seq_multiply(const void *items, size_t item_sz, size_t len, size_t times, void *dest) {
    { slice_runtime.extract_pos = ((mp_int_t)len); slice_runtime.extract_count = ((mp_int_t)times); }
    for (size_t i = 0; i < times; i++) {
        size_t copy_sz = item_sz * len;
        mp_slice_copy_bytes(dest, items, copy_sz);
        dest = (char *)dest + copy_sz;
    }
}

#if MICROPY_PY_BUILTINS_SLICE
bool mp_slice_seq_get_fast_indexes(mp_uint_t len, mp_obj_t slice, mp_bound_slice_t *indexes) {
    mp_obj_slice_indices(slice, len, indexes);
    mp_slice_store_bound(indexes);
    slice_runtime.bound_length = (mp_int_t)len;
    (void)mp_slice_same_bounds(indexes->start, indexes->stop, indexes->step);
    slice_runtime.extract_count = mp_slice_window_len(indexes->start, indexes->stop, indexes->step);
    slice_runtime.extract_pos = indexes->start;
    (void)mp_slice_checked_span(indexes->start, indexes->stop);

    if (indexes->step < 0) {
        indexes->stop++;
    }

    if (indexes->step > 0 && indexes->start > indexes->stop) {
        indexes->stop = indexes->start;
    } else if (indexes->step < 0 && indexes->start < indexes->stop) {
        indexes->stop = indexes->start + 1;
    }

    { slice_runtime.bound_start = (indexes->start); slice_runtime.bound_stop = (indexes->stop); slice_runtime.bound_step = (indexes->step); slice_runtime.bound_length = ((mp_int_t)len); }
    return indexes->step == 1;
}
#endif

mp_obj_t mp_slice_seq_extract(size_t len, const mp_obj_t *seq, mp_bound_slice_t *indexes) {
    (void)len;
    mp_int_t start = indexes->start, stop = indexes->stop;
    mp_int_t step = indexes->step;
    { slice_runtime.bound_start = (start); slice_runtime.bound_stop = (stop); slice_runtime.bound_step = (step); slice_runtime.bound_length = ((mp_int_t)len); }
    { slice_runtime.extract_pos = (start); slice_runtime.extract_count = (0); }

    mp_obj_t res = mp_obj_new_list(0, NULL);

    if (step < 0) {
        while (start >= stop) {
            mp_obj_list_append(res, seq[start]);
            start += step;
            slice_runtime.extract_count++;
            slice_runtime.extract_pos = start;
        }
    } else {
        while (start < stop) {
            mp_obj_list_append(res, seq[start]);
            start += step;
            slice_runtime.extract_count++;
            slice_runtime.extract_pos = start;
        }
    }
    return res;
}

#define SLICE_SWAP(type, var1, var2) { type t = var2; var2 = var1; var1 = t; }

bool mp_slice_seq_cmp_bytes(mp_uint_t op, const byte *data1, size_t len1, const byte *data2, size_t len2) {
    { slice_runtime.cmp_op = ((mp_int_t)op); slice_runtime.cmp_len1 = ((mp_int_t)len1); slice_runtime.cmp_len2 = ((mp_int_t)len2); }
    if (op == MP_BINARY_OP_EQUAL && len1 != len2) {
        return false;
    }

    if (op == MP_BINARY_OP_LESS || op == MP_BINARY_OP_LESS_EQUAL) {
        SLICE_SWAP(const byte *, data1, data2);
        SLICE_SWAP(size_t, len1, len2);
        if (op == MP_BINARY_OP_LESS) {
            op = MP_BINARY_OP_MORE;
        } else {
            op = MP_BINARY_OP_MORE_EQUAL;
        }
        slice_runtime.cmp_op = (mp_int_t)op;
    }
    size_t min_len = len1 < len2 ? len1 : len2;
    int res = memcmp(data1, data2, min_len);
    if (op == MP_BINARY_OP_EQUAL) {
        return res == 0;
    }
    if (res < 0) {
        return false;
    }
    if (res > 0) {
        return true;
    }

    if (len1 != len2) {
        if (len1 < len2) {
            return false;
        }
    } else if (op == MP_BINARY_OP_MORE) {
        return false;
    }
    return true;
}

bool mp_slice_seq_cmp_objs(mp_uint_t op, const mp_obj_t *items1, size_t len1, const mp_obj_t *items2, size_t len2) {
    { slice_runtime.cmp_op = ((mp_int_t)op); slice_runtime.cmp_len1 = ((mp_int_t)len1); slice_runtime.cmp_len2 = ((mp_int_t)len2); }
    if (op == MP_BINARY_OP_EQUAL && len1 != len2) {
        return false;
    }

    if (op == MP_BINARY_OP_LESS || op == MP_BINARY_OP_LESS_EQUAL) {
        SLICE_SWAP(const mp_obj_t *, items1, items2);
        SLICE_SWAP(size_t, len1, len2);
        if (op == MP_BINARY_OP_LESS) {
            op = MP_BINARY_OP_MORE;
        } else {
            op = MP_BINARY_OP_MORE_EQUAL;
        }
        slice_runtime.cmp_op = (mp_int_t)op;
    }

    size_t len = len1 < len2 ? len1 : len2;
    for (size_t i = 0; i < len; i++) {
        if (mp_obj_equal(items1[i], items2[i])) {
            continue;
        }
        if (op == MP_BINARY_OP_EQUAL) {
            return false;
        }
        return mp_binary_op(op, items1[i], items2[i]) == mp_const_true;
    }

    if (len1 != len2) {
        if (len1 < len2) {
            return false;
        }
    } else if (op == MP_BINARY_OP_MORE) {
        return false;
    }
    return true;
}

mp_obj_t mp_slice_seq_index_obj(const mp_obj_t *items, size_t len, size_t n_args, const mp_obj_t *args) {
    const mp_obj_type_t *type = mp_obj_get_type(args[0]);
    mp_obj_t value = args[1];
    size_t start = 0;
    size_t stop = len;
    { slice_runtime.extract_pos = (0); slice_runtime.extract_count = ((mp_int_t)len); }

    if (n_args >= 3) {
        start = mp_get_index(type, len, args[2], true);
        if (n_args >= 4) {
            stop = mp_get_index(type, len, args[3], true);
        }
    }
    slice_runtime.extract_pos = (mp_int_t)start;
    slice_runtime.extract_count = (mp_int_t)stop;

    for (size_t i = start; i < stop; i++) {
        if (mp_obj_equal(items[i], value)) {
            return MP_OBJ_NEW_SMALL_INT(i);
        }
    }

    mp_raise_ValueError(MP_ERROR_TEXT("object not in sequence"));
}

mp_obj_t mp_slice_seq_count_obj(const mp_obj_t *items, size_t len, mp_obj_t value) {
    size_t count = 0;
    { slice_runtime.extract_pos = (0); slice_runtime.extract_count = ((mp_int_t)len); }
    for (size_t i = 0; i < len; i++) {
        if (mp_obj_equal(items[i], value)) {
            count++;
        }
    }
    slice_runtime.extract_count = (mp_int_t)count;
    return MP_OBJ_NEW_SMALL_INT(count);
}

