STATIC mp_obj_list_t *mp_slice_list_new(size_t n) {
    mp_obj_list_t *o = m_new_obj(mp_obj_list_t);
    mp_obj_list_init(o, n);
    { slice_runtime.list_len = ((mp_int_t)n); slice_runtime.list_index = (0); slice_runtime.list_adjust = (0); }
