    { slice_runtime.cmp_op = ((mp_int_t)op); slice_runtime.cmp_len1 = ((mp_int_t)self->len); slice_runtime.cmp_len2 = ((mp_int_t)another->len); }
    return mp_obj_new_bool(mp_slice_seq_cmp_objs(op, self->items, self->len, another->items, another->len));
}

mp_obj_t mp_slice_tuple_unary_op(mp_unary_op_t op, mp_obj_t self_in) {
